// Generated by AI (UnitTest MCP)
//! Ingest a git commit as an `intent` node linked to the artifacts it touched.

use crate::error::{MindLeakError, Result};
use crate::graph::GraphStore;
use crate::ingest::{clamp, is_ignored_path, repo_relative, short_hash};
use crate::model::{Edge, Node, NodeType, RelationType};

/// A commit captured from git telemetry.
#[derive(Debug, Clone)]
pub struct CommitRecord {
    pub sha: Option<String>,
    pub message: String,
    pub changed_files: Vec<String>,
    pub timestamp: i64,
}

/// Whether a string is a full git object name: forty lowercase hex digits.
///
/// An abbreviation is refused rather than expanded. The node id is the sha
/// exactly as supplied, so `intent:7b17243` and
/// `intent:7b172432cb588a0ccda537bbe57543937f9d7e77` are two nodes for one
/// commit — the same commit recorded twice, each with half its edges. Expanding
/// it here would hide the caller's mistake instead of correcting it, and the
/// caller is the only one who can stop making it.
pub fn is_full_object_name(sha: &str) -> bool {
    sha.len() == 40
        && sha
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

/// Ask git whether this object name is a commit in the checkout we serve.
///
/// Deterministic and token-free: it reads what git already knows and decides
/// nothing (invariant 1). `cat-file -e` exits non-zero for an unknown object,
/// which is exactly the question being asked.
///
/// The environment is scrubbed because `-C` sets the working directory but does
/// not override an inherited `GIT_DIR`, and those variables win. A process
/// started from a git hook inherits them, so without this the check would
/// silently answer for a different repository than the one we were asked about
/// — and answering confidently about the wrong repository is worse than not
/// answering at all.
fn resolves_to_a_commit(root: &str, sha: &str) -> bool {
    std::process::Command::new("git")
        .args(["-C", root, "cat-file", "-e", &format!("{sha}^{{commit}}")])
        .env_remove("GIT_DIR")
        .env_remove("GIT_WORK_TREE")
        .env_remove("GIT_COMMON_DIR")
        .env_remove("GIT_INDEX_FILE")
        .env_remove("GIT_OBJECT_DIRECTORY")
        .env_remove("GIT_ALTERNATE_OBJECT_DIRECTORIES")
        .output()
        .map(|out| out.status.success())
        .unwrap_or(false)
}

/// Refuse a sha the caller cannot have read from git.
///
/// A fabricated identifier is the worst thing that can enter a memory system,
/// because it is indistinguishable from a real one afterwards and there is no
/// verb that removes a node. This has already happened: an agent holding the
/// abbreviation `7b17243` composed the remaining thirty-three characters, and
/// the resulting phantom intent node — with real edges to real files — is
/// permanent until it decays.
///
/// Checking the shape alone would not have caught it. The invention was a
/// perfectly well-formed forty-character hex string; only git can tell the
/// difference between a plausible object name and a real one. So when the
/// checkout is known, the sha is resolved, and an unresolvable one is refused
/// with the command that produces a real value.
pub fn validate_sha(sha: &str, root: Option<&str>) -> Result<()> {
    if !is_full_object_name(sha) {
        return Err(MindLeakError::Other(format!(
            "commit sha {sha:?} is not a full object name (forty lowercase hex digits). \
             An abbreviation records a second node for a commit that may already have one. \
             Use the output of `git rev-parse <ref>`, not `git log --oneline` or `--format=%h`."
        )));
    }
    match root {
        Some(root) if !resolves_to_a_commit(root, sha) => Err(MindLeakError::Other(format!(
            "commit sha {sha} does not resolve to a commit in {root}. \
             Provenance must name a commit that exists: pass the exact output of \
             `git rev-parse <ref>` rather than a value composed or remembered."
        ))),
        _ => Ok(()),
    }
}

/// Extract any explicit decision/rationale markers from a commit message or
/// inline comment (`DECISION:`, `HACK:`, `WHY:`, `NOTE:`).
pub fn extract_rationale(message: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in message.lines() {
        let trimmed = line
            .trim()
            .trim_start_matches("//")
            .trim_start_matches('#')
            .trim();
        for marker in ["DECISION:", "HACK:", "WHY:", "NOTE:", "FIXME:"] {
            if let Some(idx) = trimmed.to_ascii_uppercase().find(marker) {
                let rest = trimmed[idx + marker.len()..].trim();
                if !rest.is_empty() {
                    out.push(format!("{marker} {rest}"));
                }
            }
        }
    }
    out
}

/// Ingest one commit. Creates an intent node and `refactored` edges to files.
///
/// `root` is the checkout this process serves; changed files inside it become
/// repo-relative so every worktree writes the same node ids (ADR-0038).
pub fn ingest_commit(
    store: &GraphStore,
    rec: &CommitRecord,
    now: i64,
    root: Option<&str>,
) -> Result<crate::graph::WriteOutcome> {
    let key = match rec.sha.as_deref() {
        Some(sha) => {
            validate_sha(sha, root)?;
            sha.to_string()
        }
        None => short_hash(&format!("{}|{}", rec.message, rec.timestamp)),
    };
    let intent_id = format!("intent:{key}");
    let first_line = rec.message.lines().next().unwrap_or("").trim();
    let label = clamp(first_line, 80);

    let mut content = rec.message.clone();
    let rationale = extract_rationale(&rec.message);
    if !rationale.is_empty() {
        content.push_str("\n---\n");
        content.push_str(&rationale.join("\n"));
    }

    let intent =
        Node::new(&intent_id, NodeType::Intent, label, rec.timestamp).with_content(content);
    let mut nodes = vec![intent];
    let mut edges = Vec::new();

    let mut changed_files: Vec<String> = rec
        .changed_files
        .iter()
        .map(|file| repo_relative(file, root))
        .collect();
    changed_files.sort();
    changed_files.dedup();
    for path in changed_files {
        if is_ignored_path(&path) {
            continue;
        }
        let art_id = format!("artifact:{path}");
        let art = Node::new(&art_id, NodeType::Artifact, path.clone(), now);
        nodes.push(art);
        edges.push(Edge::new(
            &intent_id,
            &art_id,
            RelationType::Refactored,
            rec.timestamp,
        ));
    }

    let mut outcome = store.upsert_facts(&nodes, &edges)?;
    outcome.node_ids.push(intent_id);
    Ok(outcome)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pulls_decision_markers() {
        let msg = "Fix login\n\n// DECISION: use SQLite over Neo4j for footprint";
        let r = extract_rationale(msg);
        assert!(r.iter().any(|l| l.contains("SQLite over Neo4j")));
    }

    #[test]
    fn commit_edges_use_the_authoritative_record_timestamp() {
        let store = GraphStore::new(crate::db::open_in_memory().unwrap());
        // A real object name (the SHA-1 of the empty string), because a sha that
        // is not a full forty-hex-digit name is now refused.
        let sha = "da39a3ee5e6b4b0d3255bfef95601890afd80709";
        let record = CommitRecord {
            sha: Some(sha.to_string()),
            message: "fix: stable".to_string(),
            changed_files: vec!["src/lib.rs".to_string()],
            timestamp: 123,
        };
        ingest_commit(&store, &record, 999, None).unwrap();

        let graph = store
            .traverse(
                &[format!("intent:{sha}")],
                crate::graph::Direction::Outgoing,
                1,
                0.0,
                123,
            )
            .unwrap();
        assert_eq!(graph.edges[0].updated_at, 123);
    }

    /// An abbreviation is what `git log --oneline` hands you, and recording it
    /// creates a second node for a commit that may already have one.
    #[test]
    fn an_abbreviated_sha_is_refused() {
        assert!(!is_full_object_name("7b17243"));
        assert!(!is_full_object_name(
            "7B172432CB588A0CCDA537BBE57543937F9D7E77"
        ));
        assert!(is_full_object_name(
            "7b172432cb588a0ccda537bbe57543937f9d7e77"
        ));

        let error = validate_sha("7b17243", None).unwrap_err().to_string();
        assert!(error.contains("full object name"), "{error}");
        assert!(error.contains("git rev-parse"), "{error}");
    }

    /// The case that actually happened: an agent holding `7b17243` composed the
    /// remaining thirty-three characters. The result was well formed, so shape
    /// alone could never have caught it — only git can.
    #[test]
    fn a_fabricated_but_well_formed_sha_is_refused_against_a_real_checkout() {
        let dir = std::env::temp_dir().join(format!(
            "mindleak-sha-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let root = dir.to_str().unwrap().to_string();
        // `-C` changes the working directory; it does NOT override an inherited
        // GIT_DIR. Cargo runs under the pre-push hook, where git exports
        // GIT_DIR/GIT_INDEX_FILE, and those win — so without this the fixture
        // commits land in the REAL repository. That is not theoretical: this
        // test did exactly that, adding an `a.txt` commit to the branch being
        // pushed, before the scrubbing was added.
        let git = |args: &[&str]| {
            std::process::Command::new("git")
                .args(["-C", root.as_str()])
                .args(args)
                .env_remove("GIT_DIR")
                .env_remove("GIT_WORK_TREE")
                .env_remove("GIT_COMMON_DIR")
                .env_remove("GIT_INDEX_FILE")
                .env_remove("GIT_OBJECT_DIRECTORY")
                .env_remove("GIT_ALTERNATE_OBJECT_DIRECTORIES")
                .output()
                .unwrap()
        };
        git(&["init", "-b", "main"]);
        git(&["config", "user.name", "Sha Test"]);
        git(&["config", "user.email", "sha@example.invalid"]);
        std::fs::write(dir.join("a.txt"), "a\n").unwrap();
        git(&["add", "a.txt"]);
        git(&["commit", "-m", "base", "--no-verify"]);

        let real = String::from_utf8(git(&["rev-parse", "HEAD"]).stdout)
            .unwrap()
            .trim()
            .to_string();
        assert!(is_full_object_name(&real), "{real}");
        validate_sha(&real, Some(&root)).expect("a sha git can resolve is accepted");

        // Same length, same alphabet, same leading characters — and invented.
        let invented = format!("{}{}", &real[..7], "3e3b3f5e42ba4a5e0cf5d0d1e1b2f4c8a");
        assert!(is_full_object_name(&invented), "{invented}");
        let error = validate_sha(&invented, Some(&root))
            .unwrap_err()
            .to_string();
        assert!(error.contains("does not resolve"), "{error}");
        assert!(error.contains("git rev-parse"), "{error}");

        std::fs::remove_dir_all(&dir).ok();
    }

    /// Without a checkout there is nothing to resolve against, and refusing
    /// every sha would break in-memory use. The shape check still applies.
    #[test]
    fn without_a_checkout_only_the_shape_is_checked() {
        validate_sha("7b172432cb588a0ccda537bbe57543937f9d7e77", None).unwrap();
        assert!(validate_sha("nope", None).is_err());
    }
}
